async function loadReviews(){try{const e=await fetch("/api/reviews");if(!e.ok)return;const{reviews:t,rating:n,total:r}=await e.json();if(n){const e="★".repeat(Math.round(n))+"☆".repeat(5-Math.round(n));document.getElementById("reviews-stars").textContent=e,document.getElementById("reviews-score").textContent=n.toFixed(1),document.getElementById("reviews-count").textContent=`(${r} avis)`,document.getElementById("reviews-rating").style.display="flex"}if(t&&t.length){document.getElementById("reviews-container").innerHTML=t.map(e=>`\n        <blockquote>\n          <div class="review-meta">\n            <span class="review-author">${e.author_name}</span>\n            <span class="review-stars">${"★".repeat(e.rating)}${"☆".repeat(5-e.rating)}</span>\n          </div>\n          <p class="review-text">"${e.text}"</p>\n          <span class="review-date">${e.relative_time_description}</span>\n        </blockquote>\n      `).join("")}const a=document.getElementById("reviews-link");a&&(a.style.display="inline-block")}catch(e){}}"requestIdleCallback"in window?requestIdleCallback(loadReviews,{timeout:5e3}):window.addEventListener("load",loadReviews);const observer=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&e.target.classList.add("visible")})},{threshold:.12});document.querySelectorAll(".reveal").forEach(e=>observer.observe(e));const form=document.getElementById("contact-form");if(form){const e=document.getElementById("form-success");form.addEventListener("submit",async function(t){t.preventDefault();(await fetch(form.action,{method:form.method,body:new FormData(form),headers:{Accept:"application/json"}})).ok?(form.reset(),e.style.display="block"):alert("Oops… il y a un problème. Réessaie !")})}const igGrid=document.querySelector(".instagram-embed-grid");if(igGrid){new MutationObserver(()=>{igGrid.querySelectorAll("iframe:not([title])").forEach((e,t)=>{const n=e.closest(".instagram-media"),r=n?n.getAttribute("data-instgrm-permalink"):null,a=r&&r.match(/\/reel\/([^/]+)/);e.title=a?`Publication Instagram Lindsey : ${a[1]}`:`Publication Instagram Lindsey ${t+1}`})}).observe(igGrid,{childList:!0,subtree:!0});const e=()=>{if(window._igEmbedLoaded)return;window._igEmbedLoaded=!0;const e=document.createElement("script");e.async=!0,e.src="https://www.instagram.com/embed.js",document.body.appendChild(e)},t=new IntersectionObserver(n=>{n.forEach(n=>{n.isIntersecting&&(e(),t.disconnect())})},{rootMargin:"200px"});t.observe(igGrid)}const lazyVideos=document.querySelectorAll(".video-grid video[data-src]");if(lazyVideos.length){const e=new IntersectionObserver(e=>{e.forEach(e=>{const t=e.target;e.isIntersecting?(t.src||(t.src=t.dataset.src),t.play().catch(()=>{})):t.pause()})},{rootMargin:"200px"});lazyVideos.forEach(t=>e.observe(t))}const burger=document.querySelector(".burger"),navHeader=document.querySelector(".nav");burger&&(burger.addEventListener("click",()=>{const e=navHeader.classList.toggle("nav-open");burger.setAttribute("aria-expanded",e)}),document.querySelectorAll(".nav nav a").forEach(e=>{e.addEventListener("click",()=>{navHeader.classList.remove("nav-open"),burger.setAttribute("aria-expanded","false")})}));